<?php $statusCounts=[];foreach($counts as $c)$statusCounts[$c['status']]=(int)$c['count'];$eventCounts=[];foreach($events as $e)$eventCounts[$e['event_type']]=$e; ?>
<div class="space-y-5"><?php include __DIR__.'/_nav.php'; ?><div class="flex flex-wrap justify-between gap-3"><div><h1 class="text-xl font-semibold"><?= e($campaign['name']) ?></h1><p class="text-sm text-slate-500"><?= e($campaign['subject']) ?> · <?= e(ucfirst($campaign['status'])) ?></p></div><div class="flex flex-wrap gap-2"><?php if($campaign['status']==='draft'): ?><a href="/email/campaigns/<?= $campaign['id'] ?>/edit" class="px-3 py-2 border rounded text-sm">Edit</a><?php endif ?><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/duplicate"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Duplicate</button></form><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/template"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Save as template</button></form><?php if($campaign['status']==='scheduled'): ?><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/draft"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Return to draft</button></form><?php endif ?><?php if($campaign['status']==='sending'): ?><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/pause"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Pause</button></form><?php endif ?><?php if($campaign['status']==='paused'): ?><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/resume"><?= csrfField() ?><button class="px-3 py-2 border rounded text-sm">Resume</button></form><?php endif ?><?php if(in_array($campaign['status'],['scheduled','sending','paused'],true)): ?><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/cancel" onsubmit="return confirm('Cancel every recipient that has not yet been sent?')"><?= csrfField() ?><button class="px-3 py-2 border border-red-300 text-red-700 rounded text-sm">Cancel remaining</button></form><?php endif ?></div></div>
<div class="grid grid-cols-2 lg:grid-cols-5 gap-3"><?php foreach(['total_recipients'=>'Audience','delivered'=>'Delivered','opened'=>'Unique opens','clicked'=>'Unique clicks','permanent_fail'=>'Failed'] as $key=>$label): $value=$key==='total_recipients'?(int)$campaign[$key]:(int)($key==='delivered'?($statusCounts['delivered']??0):($eventCounts[$key]['unique_total']??0)); ?><div class="bg-white border rounded-lg p-4"><p class="text-xs text-slate-400"><?= $label ?></p><p class="text-2xl font-semibold mt-1"><?= $value ?></p><?php if(in_array($key,['opened','clicked'],true)&&!empty($eventCounts[$key]['bot_total'])): ?><p class="text-xs text-slate-400"><?= (int)$eventCounts[$key]['bot_total'] ?> bot events excluded</p><?php endif ?></div><?php endforeach ?></div>
<div class="grid lg:grid-cols-2 gap-5"><div class="bg-white border rounded-lg p-4"><h2 class="font-medium text-sm mb-3">Delivery states</h2><div class="space-y-2"><?php foreach($statusCounts as $status=>$count): ?><div class="flex justify-between text-sm"><span><?= e(str_replace('_',' ',$status)) ?></span><strong><?= $count ?></strong></div><?php endforeach ?><?php if(!$statusCounts): ?><p class="text-sm text-slate-400">Audience is frozen when the campaign is scheduled.</p><?php endif ?></div></div><div class="bg-white border rounded-lg p-4"><h2 class="font-medium text-sm mb-3">Top clicked links</h2><?php foreach($links as $l): ?><div class="flex gap-3 justify-between py-2 border-t text-sm"><span class="truncate"><?= e($l['url']) ?></span><strong><?= (int)$l['clicks'] ?></strong></div><?php endforeach ?><?php if(!$links): ?><p class="text-sm text-slate-400">No human-classified clicks yet.</p><?php endif ?></div></div>
<?php if(!empty($campaign['rendered_html'])): ?><details class="bg-white border rounded-lg"><summary class="p-4 cursor-pointer font-medium text-sm">Frozen email preview</summary><iframe title="Email preview" sandbox class="w-full h-[700px] border-t" srcdoc="<?= e(str_replace(['{{name}}','{{company}}','{{unsubscribe_url}}'],['Sample recipient','Sample company','#'],$campaign['rendered_html'])) ?>"></iframe></details><?php endif ?>
<?php if($recipients): ?><details class="bg-white border rounded-lg"><summary class="p-4 cursor-pointer font-medium text-sm">Recipients (<?= count($recipients) ?>)</summary><div class="max-h-96 overflow-auto"><table class="w-full text-sm"><thead class="bg-slate-50 sticky top-0"><tr><th class="text-left p-2">Recipient</th><th class="text-left p-2">Status</th><th class="text-left p-2">Error</th><th class="p-2"></th></tr></thead><tbody><?php foreach($recipients as $r): ?><tr class="border-t"><td class="p-2"><?= e($r['name']?:$r['email']) ?><div class="text-xs text-slate-400"><?= e($r['email']) ?></div></td><td class="p-2"><?= e(str_replace('_',' ',$r['status'])) ?></td><td class="p-2 text-xs text-red-600"><?= e($r['last_error']) ?></td><td class="p-2"><?php if($r['status']==='unknown'): ?><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/recipients/<?= $r['id'] ?>/retry" onsubmit="return confirm('The first attempt may have sent successfully. Retry anyway?')"><?= csrfField() ?><button class="text-xs text-red-600">Retry</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></details><?php endif ?>
